-- =====================================================================
-- B2BNest — PRODUCTION SCHEMA-ONLY BASELINE (2026-09)
-- FOR NEW STAGING / TEST ENVIRONMENTS ONLY — DO NOT RUN AGAINST PRODUCTION
-- =====================================================================
-- Generated by reading the production catalog with read-only SELECT
-- queries (pg_class, pg_attribute, pg_constraint, pg_indexes, pg_proc,
-- pg_trigger, pg_policies, aclexplode, storage.buckets metadata).
-- Contains ZERO production row data and ZERO secret values.
-- The only INSERT statements are storage bucket configuration rows
-- (bucket id/name/public flag) which are configuration, not customer data.
-- Requires the Supabase-compatible prerequisites in
-- scripts/staging/00_supabase_shim.sql (roles anon/authenticated/
-- service_role, auth/storage/vault schemas, auth.uid()/auth.jwt()).
-- =====================================================================

-- ===== EXTENSIONS =====
CREATE SCHEMA IF NOT EXISTS extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
-- Production also has: pg_cron, pg_net, pg_stat_statements, supabase_vault
-- (omitted / shimmed in staging; see 00_supabase_shim.sql)

-- ===== ENUM TYPES =====
DO $$ BEGIN
  CREATE TYPE public.app_role AS ENUM ('owner', 'admin', 'moderator', 'user', 'manager', 'super_admin');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN
  CREATE TYPE public.business_category AS ENUM ('startup', 'marketing', 'finance', 'legal', 'operations', 'hr', 'sales', 'technology', 'networking', 'general');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;


