CREATE INDEX IF NOT EXISTS idx_team_members_user_id ON public.team_members USING btree (user_id);
CREATE INDEX IF NOT EXISTS idx_todo_subtasks_todo_id ON public.todo_subtasks USING btree (todo_id);
CREATE INDEX IF NOT EXISTS idx_todos_archived_at ON public.todos USING btree (archived_at);
CREATE INDEX IF NOT EXISTS idx_todos_project_id ON public.todos USING btree (project_id);
CREATE INDEX IF NOT EXISTS idx_user_favorite_tools_tool_id ON public.user_favorite_tools USING btree (tool_id);
CREATE INDEX IF NOT EXISTS idx_user_favorite_tools_user_id ON public.user_favorite_tools USING btree (user_id);
CREATE INDEX IF NOT EXISTS idx_user_integrations_user_integration ON public.user_integrations USING btree (user_id, integration_name);
CREATE INDEX IF NOT EXISTS idx_user_stakes_status ON public.user_stakes USING btree (status);
CREATE INDEX IF NOT EXISTS idx_user_stakes_user_id ON public.user_stakes USING btree (user_id);
