-- ===== VIEWS =====
CREATE OR REPLACE VIEW public.public_profiles AS
 SELECT id, display_name, headline, bio, skills, industry, experience_years,
        created_at, avatar_url, connection_count
   FROM public.profiles
  WHERE ((is_public = true) AND (is_active = true));
-- (no materialized views in production)

GRANT SELECT ON public.public_profiles TO authenticated;
GRANT SELECT ON public.public_profiles TO service_role;
GRANT INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER ON public.public_profiles TO anon, authenticated, service_role;


-- ===== FUNCTIONS (incl. SECURITY DEFINER + search_path) =====
CREATE OR REPLACE FUNCTION public.add_project_member(p_project_id uuid, p_user_id uuid, p_role text DEFAULT 'contributor'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_org_id uuid;
  v_owner uuid;
  result JSON;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT organization_id, user_id INTO v_org_id, v_owner
  FROM public.projects WHERE id = p_project_id;

  IF v_owner IS NULL AND v_org_id IS NULL THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- Caller must own the project or administer the owning organization
  IF NOT (
    v_owner = v_caller
    OR (v_org_id IS NOT NULL AND public.user_is_organization_admin(v_org_id, v_caller))
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  -- Target user must belong to the same tenant as the project
  IF NOT (
    p_user_id = v_owner
    OR (v_org_id IS NOT NULL AND public.user_is_organization_member(v_org_id, p_user_id))
    OR public.users_share_organization(v_caller, p_user_id)
  ) THEN
    RAISE EXCEPTION 'Not authorized: user does not belong to this company';
  END IF;

  INSERT INTO public.project_members (project_id, user_id, role)
  VALUES (p_project_id, p_user_id, p_role)
  ON CONFLICT (project_id, user_id)
  DO UPDATE SET role = EXCLUDED.role
  RETURNING to_json(project_members.*) INTO result;

  RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.add_team_member(p_team_id uuid, p_user_id uuid, p_role text DEFAULT 'member'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_owner uuid;
  result JSON;
BEGIN
  IF v_caller IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT owner_id INTO v_owner FROM public.teams WHERE id = p_team_id;
  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF v_owner <> v_caller THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF NOT (p_user_id = v_caller OR public.users_share_organization(v_caller, p_user_id)) THEN
    RAISE EXCEPTION 'Not authorized: user does not belong to this company';
  END IF;

  INSERT INTO public.team_members (team_id, user_id, role)
  VALUES (p_team_id, p_user_id, p_role)
  ON CONFLICT (team_id, user_id)
  DO UPDATE SET role = EXCLUDED.role
  RETURNING to_json(team_members.*) INTO result;

  RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.admin_ai_stats(_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  RETURN jsonb_build_object(
    'total', (SELECT count(*) FROM public.ai_conversations),
    'today', (SELECT count(*) FROM public.ai_conversations WHERE created_at > date_trunc('day', now())),
    'this_month', (SELECT count(*) FROM public.ai_conversations WHERE created_at > date_trunc('month', now())),
    'credits_used', (SELECT COALESCE(sum(GREATEST(ai_credits_limit - ai_credits_remaining,0)),0) FROM public.subscribers),
    'by_feature', (SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (
        SELECT COALESCE(conversation_type,'other') AS feature, count(*) AS count
        FROM public.ai_conversations GROUP BY 1 ORDER BY 2 DESC) x),
    'by_user', (SELECT COALESCE(jsonb_agg(y),'[]'::jsonb) FROM (
        SELECT (SELECT COALESCE(pr.display_name, pr.full_name, pr.email) FROM public.profiles pr WHERE pr.id = ac.user_id) AS user_name,
               count(*) AS count
        FROM public.ai_conversations ac GROUP BY ac.user_id ORDER BY 2 DESC LIMIT 10) y),
    'series', (SELECT COALESCE(jsonb_agg(z ORDER BY z.day),'[]'::jsonb) FROM (
        SELECT to_char(d.day,'YYYY-MM-DD') AS day,
          (SELECT count(*) FROM public.ai_conversations ac WHERE ac.created_at::date = d.day) AS count
        FROM generate_series((now() - (GREATEST(_days,1) || ' days')::interval)::date, now()::date, interval '1 day') AS d(day)) z)
  );
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_analytics_series(_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  RETURN (SELECT COALESCE(jsonb_agg(z ORDER BY z.day),'[]'::jsonb) FROM (
    SELECT to_char(d.day,'YYYY-MM-DD') AS day,
      (SELECT count(*) FROM public.profiles p WHERE p.created_at::date = d.day) AS users,
      (SELECT count(*) FROM public.projects pr WHERE pr.created_at::date = d.day) AS projects,
      (SELECT count(*) FROM public.documents dc WHERE dc.created_at::date = d.day) AS documents,
      (SELECT count(*) FROM public.ai_conversations ac WHERE ac.created_at::date = d.day) AS ai,
      (SELECT count(*) FROM public.social_posts sp WHERE sp.created_at::date = d.day) AS social,
      (SELECT COALESCE(sum(pay.amount),0)/100.0 FROM public.payments pay WHERE pay.created_at::date = d.day AND pay.status IN ('paid','succeeded','complete','completed')) AS revenue
    FROM generate_series((now() - (GREATEST(_days,1) || ' days')::interval)::date, now()::date, interval '1 day') AS d(day)) z);
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_company_detail(_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE result jsonb; v_owner uuid; v_member_ids uuid[]; v_plan record;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  SELECT created_by INTO v_owner FROM public.organizations WHERE id = _org_id;
  SELECT COALESCE(array_agg(DISTINCT uid),'{}') INTO v_member_ids FROM (
    SELECT m.user_id AS uid FROM public.organization_members m WHERE m.organization_id = _org_id
    UNION SELECT v_owner WHERE v_owner IS NOT NULL
  ) x WHERE uid IS NOT NULL;

  SELECT pl.* INTO v_plan FROM public.platform_plans pl
   WHERE lower(pl.key) = lower(COALESCE(
     (SELECT s.subscription_tier FROM public.subscribers s WHERE s.user_id = v_owner ORDER BY s.updated_at DESC NULLS LAST LIMIT 1),
     (SELECT o.subscription_tier FROM public.organizations o WHERE o.id = _org_id), ''))
   LIMIT 1;

  SELECT jsonb_build_object(
    'company', (SELECT to_jsonb(c) FROM (
        SELECT o.id, o.name, o.slug, o.description, o.created_at, o.updated_at,
               COALESCE(o.is_active,true) AS is_active, o.status, o.suspended_at, o.suspension_reason,
               COALESCE(NULLIF(o.subscription_tier,''),'free') AS plan_key,
               COALESCE(p.display_name, p.full_name, p.email) AS owner_name, p.email AS owner_email, p.id AS owner_id
        FROM public.organizations o LEFT JOIN public.profiles p ON p.id = o.created_by WHERE o.id = _org_id) c),
    'users', (SELECT COALESCE(jsonb_agg(u ORDER BY u.joined_at NULLS LAST),'[]'::jsonb) FROM (
        SELECT pr.id, pr.email, COALESCE(pr.display_name, pr.full_name) AS name,
               CASE WHEN pr.id = v_owner THEN 'COMPANY_OWNER' ELSE upper(COALESCE(m.role,'member')) END AS company_role,
               COALESCE(pr.is_active,true) AS is_active, m.joined_at, pr.created_at,
               (SELECT au.last_sign_in_at FROM auth.users au WHERE au.id = pr.id) AS last_login
        FROM public.profiles pr
        LEFT JOIN public.organization_members m ON m.user_id = pr.id AND m.organization_id = _org_id
        WHERE pr.id = ANY(v_member_ids)) u),
    'subscription', (SELECT to_jsonb(s2) FROM (
        SELECT s.subscribed, s.subscription_tier, s.subscription_end AS renewal_date, s.updated_at,
               COALESCE(pr.is_trial_active,false) AS is_trial_active, pr.trial_ends_at,
               s.ai_credits_remaining, s.ai_credits_limit
        FROM public.profiles pr LEFT JOIN public.subscribers s ON s.user_id = pr.id
        WHERE pr.id = v_owner ORDER BY s.updated_at DESC NULLS LAST LIMIT 1) s2),
    'plan', CASE WHEN v_plan.id IS NULL THEN NULL ELSE jsonb_build_object(
        'key', v_plan.key, 'name', v_plan.name, 'monthly_price', v_plan.monthly_price,
        'annual_price', v_plan.annual_price, 'currency', v_plan.currency,
        'member_limit', v_plan.member_limit, 'project_limit', v_plan.project_limit,
        'ai_credit_limit', v_plan.ai_credit_limit, 'storage_limit_mb', v_plan.storage_limit_mb,
        'document_limit', v_plan.document_limit) END,
    'usage', jsonb_build_object(
        'users', cardinality(v_member_ids),
        'projects', (SELECT count(*) FROM public.projects p WHERE p.organization_id = _org_id AND p.deleted_at IS NULL),
        'tasks', (SELECT count(*) FROM public.todos t WHERE t.user_id = ANY(v_member_ids)),
        'crm_contacts', (SELECT count(*) FROM public.crm_contacts c WHERE c.user_id = ANY(v_member_ids)),
        'crm_deals', (SELECT count(*) FROM public.crm_deals d WHERE d.user_id = ANY(v_member_ids)),
        'invoices', (SELECT count(*) FROM public.invoices i WHERE i.user_id = ANY(v_member_ids)),
        'invoice_total', (SELECT COALESCE(sum(i.total_amount),0) FROM public.invoices i WHERE i.user_id = ANY(v_member_ids)),
        'quotes', (SELECT count(*) FROM public.quotes q WHERE q.user_id = ANY(v_member_ids)),
        'documents', (SELECT count(*) FROM public.documents d WHERE d.user_id = ANY(v_member_ids)),
        'storage_bytes', (SELECT COALESCE(sum(d.file_size),0) FROM public.documents d WHERE d.user_id = ANY(v_member_ids)),
        'ai_conversations', (SELECT count(*) FROM public.ai_conversations a WHERE a.user_id = ANY(v_member_ids)),
        'ai_workflows', (SELECT count(*) FROM public.ai_workflows w WHERE w.user_id = ANY(v_member_ids))),
    'activity', (SELECT COALESCE(jsonb_agg(a ORDER BY a.created_at DESC),'[]'::jsonb) FROM (
        SELECT COALESCE(pa.title, pa.activity_type) AS action, pa.created_at, pa.user_id, p.name AS project_name
        FROM public.project_activities pa
        JOIN public.projects p ON p.id = pa.project_id
        WHERE p.organization_id = _org_id ORDER BY pa.created_at DESC LIMIT 20) a),
    'security', (SELECT COALESCE(jsonb_agg(s ORDER BY s.created_at DESC),'[]'::jsonb) FROM (
        SELECT sa.action AS event_type, sa.created_at, sa.user_id
        FROM public.security_audit_logs sa WHERE sa.user_id = ANY(v_member_ids)
        ORDER BY sa.created_at DESC LIMIT 20) s),
    'admin_actions', (SELECT COALESCE(jsonb_agg(al ORDER BY al.created_at DESC),'[]'::jsonb) FROM (
        SELECT l.action, l.admin_email, l.created_at, l.details
        FROM public.admin_audit_logs l
        WHERE l.target_id = _org_id::text OR l.target_id = ANY(SELECT unnest(v_member_ids)::text)
        ORDER BY l.created_at DESC LIMIT 20) al)
  ) INTO result;
  RETURN result;
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_documents_summary(_limit integer DEFAULT 25, _offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE rows jsonb; total integer; cats jsonb;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  SELECT COALESCE(jsonb_agg(t ORDER BY t.created_at DESC),'[]'::jsonb) INTO rows FROM (
    SELECT d.id, d.title, d.category, d.file_size, d.created_at,
      (SELECT COALESCE(pr.display_name, pr.full_name, pr.email) FROM public.profiles pr WHERE pr.id = d.user_id) AS owner
    FROM public.documents d ORDER BY d.created_at DESC LIMIT GREATEST(_limit,1) OFFSET GREATEST(_offset,0)) t;
  SELECT count(*) INTO total FROM public.documents;
  SELECT COALESCE(jsonb_agg(c),'[]'::jsonb) INTO cats FROM (
    SELECT COALESCE(category,'uncategorised') AS category, count(*) AS count FROM public.documents GROUP BY 1 ORDER BY 2 DESC LIMIT 10) c;
  RETURN jsonb_build_object('rows', rows, 'total', total, 'categories', cats,
    'this_month', (SELECT count(*) FROM public.documents WHERE created_at > date_trunc('month', now())),
    'storage_bytes', (SELECT COALESCE(sum(file_size),0) FROM public.documents));
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_list_companies(_search text DEFAULT NULL::text, _limit integer DEFAULT 25, _offset integer DEFAULT 0, _status text DEFAULT NULL::text, _plan text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE rows jsonb; total integer;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  WITH base AS (
    SELECT o.id, o.name,
      COALESCE(NULLIF(o.subscription_tier,''),'free') AS plan,
      COALESCE(o.is_active,true) AS is_active,
      o.created_at, o.suspended_at, o.suspension_reason,
      owner.id AS owner_id,
      COALESCE(owner.display_name, owner.full_name, owner.email) AS owner,
      owner.email AS owner_email,
      (SELECT count(*) FROM public.organization_members m WHERE m.organization_id = o.id) AS members,
      (SELECT count(*) FROM public.projects p WHERE p.organization_id = o.id AND p.deleted_at IS NULL) AS projects,
      (SELECT max(p.updated_at) FROM public.projects p WHERE p.organization_id = o.id) AS last_activity,
      CASE
        WHEN o.status IN ('suspended','cancelled') THEN o.status
        WHEN COALESCE(o.is_active,true) = false THEN 'suspended'
        WHEN EXISTS (SELECT 1 FROM public.subscribers s WHERE s.user_id = o.created_by AND s.subscribed = true) THEN 'active'
        WHEN COALESCE(owner.is_trial_active,false) THEN 'trial'
        ELSE COALESCE(NULLIF(o.status,''),'active')
      END AS status,
      (SELECT s.subscribed FROM public.subscribers s WHERE s.user_id = o.created_by ORDER BY s.updated_at DESC NULLS LAST LIMIT 1) AS subscribed,
      (SELECT s.subscription_tier FROM public.subscribers s WHERE s.user_id = o.created_by ORDER BY s.updated_at DESC NULLS LAST LIMIT 1) AS subscription_plan,
      (SELECT s.subscription_end FROM public.subscribers s WHERE s.user_id = o.created_by ORDER BY s.updated_at DESC NULLS LAST LIMIT 1) AS renewal_date
    FROM public.organizations o
    LEFT JOIN public.profiles owner ON owner.id = o.created_by
    WHERE (_search IS NULL OR _search = ''
       OR o.name ILIKE '%'||_search||'%'
       OR COALESCE(owner.email,'') ILIKE '%'||_search||'%'
       OR COALESCE(owner.display_name, owner.full_name,'') ILIKE '%'||_search||'%'
       OR o.id::text = _search)
  ), filtered AS (
    SELECT * FROM base
    WHERE (_status IS NULL OR _status = 'all' OR status = _status)
      AND (_plan IS NULL OR _plan = 'all' OR lower(COALESCE(subscription_plan, plan)) = lower(_plan))
  )
  SELECT COALESCE(jsonb_agg(t ORDER BY t.created_at DESC),'[]'::jsonb), (SELECT count(*) FROM filtered)
  INTO rows, total
  FROM (SELECT * FROM filtered ORDER BY created_at DESC LIMIT GREATEST(_limit,1) OFFSET GREATEST(_offset,0)) t;
  RETURN jsonb_build_object('rows', rows, 'total', total);
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_list_projects(_search text DEFAULT NULL::text, _status text DEFAULT NULL::text, _limit integer DEFAULT 25, _offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE rows jsonb; total integer;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  WITH base AS (
    SELECT p.id, p.name, p.status, p.progress, p.deadline, p.created_at, p.updated_at, p.archived_at,
      (SELECT o.name FROM public.organizations o WHERE o.id = p.organization_id) AS company,
      (SELECT COALESCE(pr.display_name, pr.full_name, pr.email) FROM public.profiles pr WHERE pr.id = p.user_id) AS owner,
      (SELECT count(*) FROM public.todos t WHERE t.project_id = p.id) AS tasks
    FROM public.projects p
    WHERE p.deleted_at IS NULL
      AND (_search IS NULL OR _search='' OR p.name ILIKE '%'||_search||'%')
      AND (_status IS NULL OR _status='all' OR COALESCE(p.status,'active') = _status)
  )
  SELECT COALESCE(jsonb_agg(t ORDER BY t.created_at DESC),'[]'::jsonb), (SELECT count(*) FROM base)
  INTO rows, total
  FROM (SELECT * FROM base ORDER BY created_at DESC LIMIT GREATEST(_limit,1) OFFSET GREATEST(_offset,0)) t;
  RETURN jsonb_build_object('rows', rows, 'total', total);
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_list_subscriptions(_status text DEFAULT NULL::text, _search text DEFAULT NULL::text, _limit integer DEFAULT 25, _offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE rows jsonb; total integer;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  WITH base AS (
    SELECT s.id, s.email, s.subscription_tier AS plan, s.subscribed, s.subscription_end, s.created_at, s.updated_at,
      s.ai_credits_remaining, s.ai_credits_limit,
      p.company, COALESCE(p.is_trial_active,false) AS is_trial_active,
      COALESCE((SELECT pl.monthly_price FROM public.platform_plans pl WHERE lower(pl.key) = lower(COALESCE(s.subscription_tier,''))),0) AS value,
      CASE WHEN s.subscribed THEN 'active'
           WHEN COALESCE(p.is_trial_active,false) THEN 'trial'
           WHEN s.subscription_end IS NOT NULL AND s.subscription_end < now() THEN 'cancelled'
           ELSE 'free' END AS status
    FROM public.subscribers s
    LEFT JOIN public.profiles p ON p.id = s.user_id
    WHERE (_search IS NULL OR _search = '' OR s.email ILIKE '%'||_search||'%')
  ), filtered AS (SELECT * FROM base WHERE _status IS NULL OR _status='all' OR status = _status)
  SELECT COALESCE(jsonb_agg(t ORDER BY t.created_at DESC),'[]'::jsonb), (SELECT count(*) FROM filtered)
  INTO rows, total
  FROM (SELECT * FROM filtered ORDER BY created_at DESC LIMIT GREATEST(_limit,1) OFFSET GREATEST(_offset,0)) t;
  RETURN jsonb_build_object('rows', rows, 'total', total);
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_list_users(_search text DEFAULT NULL::text, _status text DEFAULT NULL::text, _limit integer DEFAULT 25, _offset integer DEFAULT 0, _plan text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE rows jsonb; total integer;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  WITH base AS (
    SELECT p.id, p.email, COALESCE(p.display_name, p.full_name) AS name, p.company, p.created_at,
           COALESCE(p.is_active, true) AS is_active, p.is_trial_active, p.trial_ends_at,
           (SELECT au.last_sign_in_at FROM auth.users au WHERE au.id = p.id) AS last_login,
           (SELECT o.name FROM public.organizations o WHERE o.created_by = p.id ORDER BY o.created_at LIMIT 1) AS owned_company,
           (SELECT o.id FROM public.organizations o
              JOIN public.organization_members m ON m.organization_id = o.id AND m.user_id = p.id
              ORDER BY m.joined_at NULLS LAST LIMIT 1) AS organization_id,
           (SELECT o.name FROM public.organizations o
              JOIN public.organization_members m ON m.organization_id = o.id AND m.user_id = p.id
              ORDER BY m.joined_at NULLS LAST LIMIT 1) AS organization_name,
           (SELECT upper(m.role) FROM public.organization_members m WHERE m.user_id = p.id ORDER BY m.joined_at NULLS LAST LIMIT 1) AS company_role,
           (SELECT s.subscription_tier FROM public.subscribers s WHERE s.user_id = p.id ORDER BY s.updated_at DESC NULLS LAST LIMIT 1) AS plan,
           (SELECT s.subscribed FROM public.subscribers s WHERE s.user_id = p.id ORDER BY s.updated_at DESC NULLS LAST LIMIT 1) AS subscribed,
           (SELECT count(*) FROM public.projects pr WHERE pr.user_id = p.id AND pr.deleted_at IS NULL) AS projects,
           (SELECT count(*) FROM public.documents d WHERE d.user_id = p.id) AS documents,
           (SELECT count(*) FROM public.ai_conversations ac WHERE ac.user_id = p.id) AS ai_usage,
           (SELECT r.role::text FROM public.user_roles r WHERE r.user_id = p.id ORDER BY r.created_at LIMIT 1) AS role
    FROM public.profiles p
    WHERE (_search IS NULL OR _search = '' OR p.email ILIKE '%'||_search||'%' OR COALESCE(p.display_name,p.full_name,'') ILIKE '%'||_search||'%' OR COALESCE(p.company,'') ILIKE '%'||_search||'%')
  ), filtered AS (
    SELECT * FROM base WHERE (_status IS NULL OR _status = 'all'
      OR (_status = 'active' AND is_active)
      OR (_status = 'suspended' AND NOT is_active)
      OR (_status = 'paid' AND subscribed)
      OR (_status = 'free' AND COALESCE(subscribed,false) = false)
      OR (_status = 'trial' AND is_trial_active))
    AND (_plan IS NULL OR _plan = 'all' OR lower(COALESCE(plan,'free')) = lower(_plan))
  )
  SELECT COALESCE(jsonb_agg(t ORDER BY t.created_at DESC), '[]'::jsonb), (SELECT count(*) FROM filtered)
  INTO rows, total
  FROM (SELECT * FROM filtered ORDER BY created_at DESC LIMIT GREATEST(_limit,1) OFFSET GREATEST(_offset,0)) t;
  RETURN jsonb_build_object('rows', rows, 'total', total);
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_log_action(_action text, _target_type text DEFAULT NULL::text, _target_id text DEFAULT NULL::text, _details jsonb DEFAULT '{}'::jsonb, _status text DEFAULT 'success'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  INSERT INTO public.admin_audit_logs(admin_id, admin_email, action, target_type, target_id, details, status)
  VALUES (auth.uid(), (SELECT email FROM public.profiles WHERE id = auth.uid()), _action, _target_type, _target_id, COALESCE(_details,'{}'::jsonb), COALESCE(_status,'success'))
  RETURNING id INTO v_id;
  RETURN v_id;
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_moderate_post(_post_id uuid, _hide boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  UPDATE public.social_posts SET is_public = NOT _hide, updated_at = now() WHERE id = _post_id;
  PERFORM public.admin_log_action(CASE WHEN _hide THEN 'social.post_hidden' ELSE 'social.post_restored' END, 'social_post', _post_id::text, '{}'::jsonb, 'success');
  RETURN true;
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_overview_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE result jsonb; v_mrr numeric;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  SELECT COALESCE(sum(pl.monthly_price),0) INTO v_mrr
    FROM public.subscribers s LEFT JOIN public.platform_plans pl ON lower(pl.key) = lower(COALESCE(s.subscription_tier,''))
   WHERE s.subscribed = true;
  SELECT jsonb_build_object(
    'total_users', (SELECT count(*) FROM public.profiles),
    'new_users_30d', (SELECT count(*) FROM public.profiles WHERE created_at > now() - interval '30 days'),
    'new_users_prev_30d', (SELECT count(*) FROM public.profiles WHERE created_at > now() - interval '60 days' AND created_at <= now() - interval '30 days'),
    'active_users', (SELECT count(*) FROM public.profiles WHERE COALESCE(is_active, true)),
    'suspended_users', (SELECT count(*) FROM public.profiles WHERE is_active = false),
    'total_companies', (SELECT count(*) FROM public.organizations),
    'active_companies', (SELECT count(*) FROM public.organizations WHERE COALESCE(is_active,true) AND COALESCE(status,'active') NOT IN ('suspended','cancelled')),
    'trial_companies', (SELECT count(*) FROM public.organizations o JOIN public.profiles p ON p.id = o.created_by
                         WHERE COALESCE(p.is_trial_active,false) AND COALESCE(o.status,'active') NOT IN ('suspended','cancelled')),
    'suspended_companies', (SELECT count(*) FROM public.organizations WHERE status = 'suspended' OR is_active = false),
    'cancelled_companies', (SELECT count(*) FROM public.organizations WHERE status = 'cancelled'),
    'new_companies_30d', (SELECT count(*) FROM public.organizations WHERE created_at > now() - interval '30 days'),
    'total_subscribers', (SELECT count(*) FROM public.subscribers),
    'active_subscriptions', (SELECT count(*) FROM public.subscribers WHERE subscribed = true),
    'trials', (SELECT count(*) FROM public.profiles WHERE is_trial_active = true),
    'free_users', (SELECT count(*) FROM public.profiles p WHERE NOT EXISTS (SELECT 1 FROM public.subscribers s WHERE s.user_id = p.id AND s.subscribed = true)),
    'mrr', v_mrr,
    'arr', v_mrr * 12,
    'total_revenue', (SELECT COALESCE(sum(amount),0)/100.0 FROM public.payments WHERE status IN ('paid','succeeded','complete','completed')),
    'revenue_30d', (SELECT COALESCE(sum(amount),0)/100.0 FROM public.payments WHERE status IN ('paid','succeeded','complete','completed') AND created_at > now() - interval '30 days'),
    'revenue_prev_30d', (SELECT COALESCE(sum(amount),0)/100.0 FROM public.payments WHERE status IN ('paid','succeeded','complete','completed') AND created_at > now() - interval '60 days' AND created_at <= now() - interval '30 days'),
    'ai_requests', (SELECT count(*) FROM public.ai_conversations),
    'ai_requests_30d', (SELECT count(*) FROM public.ai_conversations WHERE created_at > now() - interval '30 days'),
    'total_projects', (SELECT count(*) FROM public.projects WHERE deleted_at IS NULL),
    'active_projects', (SELECT count(*) FROM public.projects WHERE deleted_at IS NULL AND archived_at IS NULL AND COALESCE(status,'active') <> 'completed'),
    'documents', (SELECT count(*) FROM public.documents),
    'documents_30d', (SELECT count(*) FROM public.documents WHERE created_at > now() - interval '30 days'),
    'storage_bytes', (SELECT COALESCE(sum(file_size),0) FROM public.documents),
    'support_open', (SELECT count(*) FROM public.feedback_requests WHERE COALESCE(status,'open') NOT IN ('resolved','closed')),
    'support_total', (SELECT count(*) FROM public.feedback_requests),
    'social_posts', (SELECT count(*) FROM public.social_posts),
    'social_posts_7d', (SELECT count(*) FROM public.social_posts WHERE created_at > now() - interval '7 days'),
    'forum_posts', (SELECT count(*) FROM public.forum_posts)
  ) INTO result;
  RETURN result;
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_set_company_status(_org_id uuid, _status text, _reason text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF _status NOT IN ('active','trial','suspended','cancelled') THEN RAISE EXCEPTION 'Invalid status'; END IF;
  UPDATE public.organizations
  SET status = _status,
      is_active = (_status <> 'suspended'),
      suspended_at = CASE WHEN _status = 'suspended' THEN now() ELSE NULL END,
      suspension_reason = CASE WHEN _status = 'suspended' THEN _reason ELSE NULL END,
      updated_at = now()
  WHERE id = _org_id;
  PERFORM public.admin_log_action('company.status_changed','organization',_org_id::text,
    jsonb_build_object('status',_status,'reason',_reason),'success');
  RETURN true;
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_set_user_role(_user_id uuid, _role app_role)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF _user_id = auth.uid() THEN RAISE EXCEPTION 'You cannot change your own role'; END IF;
  DELETE FROM public.user_roles WHERE user_id = _user_id;
  INSERT INTO public.user_roles(user_id, role) VALUES (_user_id, _role) ON CONFLICT DO NOTHING;
  PERFORM public.admin_log_action('user.role_changed', 'user', _user_id::text, jsonb_build_object('role', _role::text), 'success');
  RETURN true;
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_set_user_status(_user_id uuid, _active boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  IF _user_id = auth.uid() THEN RAISE EXCEPTION 'You cannot change your own status'; END IF;
  UPDATE public.profiles SET is_active = _active, updated_at = now() WHERE id = _user_id;
  PERFORM public.admin_log_action(CASE WHEN _active THEN 'user.reactivated' ELSE 'user.suspended' END, 'user', _user_id::text, '{}'::jsonb, 'success');
  RETURN true;
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_social_stats(_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  RETURN jsonb_build_object(
    'total_posts', (SELECT count(*) FROM public.social_posts),
    'posts_today', (SELECT count(*) FROM public.social_posts WHERE created_at > date_trunc('day', now())),
    'posts_week', (SELECT count(*) FROM public.social_posts WHERE created_at > now() - interval '7 days'),
    'comments', (SELECT count(*) FROM public.post_comments),
    'likes', (SELECT count(*) FROM public.post_likes),
    'forum_posts', (SELECT count(*) FROM public.forum_posts),
    'active_authors', (SELECT count(DISTINCT user_id) FROM public.social_posts WHERE created_at > now() - interval '30 days'),
    'top_authors', (SELECT COALESCE(jsonb_agg(x),'[]'::jsonb) FROM (
      SELECT (SELECT COALESCE(pr.display_name, pr.full_name, pr.email) FROM public.profiles pr WHERE pr.id = sp.user_id) AS author, count(*) AS posts
      FROM public.social_posts sp GROUP BY sp.user_id ORDER BY 2 DESC LIMIT 10) x),
    'recent_posts', (SELECT COALESCE(jsonb_agg(y ORDER BY y.created_at DESC),'[]'::jsonb) FROM (
      SELECT sp.id, left(sp.content, 240) AS content, sp.like_count, sp.comment_count, sp.is_public, sp.created_at,
        (SELECT COALESCE(pr.display_name, pr.full_name, pr.email) FROM public.profiles pr WHERE pr.id = sp.user_id) AS author
      FROM public.social_posts sp ORDER BY sp.created_at DESC LIMIT GREATEST(_limit,1)) y)
  );
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_support_overview(_status text DEFAULT NULL::text, _limit integer DEFAULT 25, _offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE rows jsonb; total integer;
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  WITH base AS (
    SELECT f.id, f.title, f.type, f.category, f.priority, f.status, f.created_at, f.updated_at, f.admin_response,
      (SELECT COALESCE(pr.display_name, pr.full_name, pr.email) FROM public.profiles pr WHERE pr.id = f.user_id) AS requester
    FROM public.feedback_requests f
    WHERE _status IS NULL OR _status='all' OR COALESCE(f.status,'open') = _status
  )
  SELECT COALESCE(jsonb_agg(t ORDER BY t.created_at DESC),'[]'::jsonb), (SELECT count(*) FROM base)
  INTO rows, total
  FROM (SELECT * FROM base ORDER BY created_at DESC LIMIT GREATEST(_limit,1) OFFSET GREATEST(_offset,0)) t;
  RETURN jsonb_build_object('rows', rows, 'total', total,
    'open', (SELECT count(*) FROM public.feedback_requests WHERE COALESCE(status,'open')='open'),
    'pending', (SELECT count(*) FROM public.feedback_requests WHERE status='pending'),
    'resolved', (SELECT count(*) FROM public.feedback_requests WHERE status IN ('resolved','closed')),
    'urgent', (SELECT count(*) FROM public.feedback_requests WHERE priority IN ('urgent','high')));
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_system_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  RETURN jsonb_build_object(
    'database', 'healthy',
    'auth_users', (SELECT count(*) FROM public.profiles),
    'payments_configured', (SELECT count(*) > 0 FROM public.payments),
    'ai_configured', (SELECT count(*) > 0 FROM public.ai_conversations),
    'integrations_connected', (SELECT count(*) FROM public.user_integrations WHERE is_connected = true),
    'storage_bytes', (SELECT COALESCE(sum(file_size),0) FROM public.documents),
    'recent_admin_errors', (SELECT count(*) FROM public.admin_audit_logs WHERE status <> 'success' AND created_at > now() - interval '7 days'),
    'checked_at', to_char(now(), 'YYYY-MM-DD HH24:MI:SS')
  );
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_tools_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  RETURN (SELECT COALESCE(jsonb_agg(x ORDER BY x.name),'[]'::jsonb) FROM (
    SELECT t.id, t.key, t.name, t.category, t.is_active,
      CASE t.key
        WHEN 'crm' THEN (SELECT count(*) FROM public.crm_contacts)
        WHEN 'project_management' THEN (SELECT count(*) FROM public.projects WHERE deleted_at IS NULL)
        WHEN 'ai_tools' THEN (SELECT count(*) FROM public.ai_conversations)
        WHEN 'templates' THEN (SELECT count(*) FROM public.documents)
        WHEN 'rota' THEN (SELECT count(*) FROM public.rota_shifts)
        WHEN 'financial_dashboard' THEN (SELECT count(*) FROM public.invoices)
        WHEN 'workflow_automation' THEN (SELECT count(*) FROM public.ai_workflows)
        ELSE 0 END AS usage,
      CASE t.key
        WHEN 'crm' THEN (SELECT count(DISTINCT user_id) FROM public.crm_contacts)
        WHEN 'project_management' THEN (SELECT count(DISTINCT user_id) FROM public.projects)
        WHEN 'ai_tools' THEN (SELECT count(DISTINCT user_id) FROM public.ai_conversations)
        WHEN 'templates' THEN (SELECT count(DISTINCT user_id) FROM public.documents)
        WHEN 'financial_dashboard' THEN (SELECT count(DISTINCT user_id) FROM public.invoices)
        WHEN 'workflow_automation' THEN (SELECT count(DISTINCT user_id) FROM public.ai_workflows)
        ELSE 0 END AS users
    FROM public.platform_tools t) x);
END; $function$
;

CREATE OR REPLACE FUNCTION public.admin_update_company(_org_id uuid, _name text DEFAULT NULL::text, _plan text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Not authorized'; END IF;
  UPDATE public.organizations
  SET name = COALESCE(NULLIF(_name,''), name),
      subscription_tier = COALESCE(NULLIF(_plan,''), subscription_tier),
      updated_at = now()
  WHERE id = _org_id;
  PERFORM public.admin_log_action('company.updated','organization',_org_id::text,
    jsonb_build_object('name',_name,'plan',_plan),'success');
  RETURN true;
END; $function$
;

CREATE OR REPLACE FUNCTION public.audit_profile_access(accessed_user_id uuid, access_type text DEFAULT 'profile_viewed'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  -- Only log if it's not the user viewing their own profile
  IF auth.uid() != accessed_user_id THEN
    INSERT INTO public.audit_logs (
      user_id,
      action,
      resource_type,
      resource_id,
      details,
      ip_address
    )
    VALUES (
      auth.uid(),
      access_type,
      'profile',
      accessed_user_id::text,
      jsonb_build_object(
        'accessed_at', now(),
        'target_user', accessed_user_id
      ),
      inet_client_addr()
    );
  END IF;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_2fa_rate_limit(p_email text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  attempt_record RECORD;
  current_time timestamp with time zone := now();
BEGIN
  -- Get or create attempt record
  SELECT * INTO attempt_record 
  FROM public.user_2fa_attempts 
  WHERE email = p_email 
  ORDER BY created_at DESC 
  LIMIT 1;
  
  -- If no record exists or it's been more than 5 minutes, allow
  IF attempt_record IS NULL OR 
     (current_time - attempt_record.last_attempt_at) > interval '5 minutes' THEN
    
    -- Reset or create new record
    INSERT INTO public.user_2fa_attempts (email, attempt_count, last_attempt_at)
    VALUES (p_email, 1, current_time)
    ON CONFLICT (email) DO UPDATE SET
      attempt_count = 1,
      last_attempt_at = current_time,
      blocked_until = NULL;
    
    RETURN true;
  END IF;
  
  -- If currently blocked, check if block period is over
  IF attempt_record.blocked_until IS NOT NULL AND 
     current_time < attempt_record.blocked_until THEN
    RETURN false;
  END IF;
  
  -- If less than 3 attempts in 5 minutes, allow
  IF attempt_record.attempt_count < 3 THEN
    UPDATE public.user_2fa_attempts 
    SET attempt_count = attempt_count + 1,
        last_attempt_at = current_time
    WHERE email = p_email;
    RETURN true;
  END IF;
  
  -- Block for 15 minutes after 3 attempts
  UPDATE public.user_2fa_attempts 
  SET blocked_until = current_time + interval '15 minutes',
      last_attempt_at = current_time
  WHERE email = p_email;
  
  RETURN false;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_and_deduct_ai_credit(p_user_id uuid, p_credits_to_deduct integer DEFAULT 1)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_subscriber RECORD;
  v_result JSON;
BEGIN
  IF NOT (
    auth.uid() = p_user_id
    OR COALESCE(auth.role(), current_user) IN ('service_role', 'postgres', 'supabase_admin')
  ) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  IF p_credits_to_deduct IS NULL OR p_credits_to_deduct < 1 OR p_credits_to_deduct > 1000 THEN
    RAISE EXCEPTION 'Invalid credit amount';
  END IF;

  SELECT * INTO v_subscriber FROM public.subscribers WHERE user_id = p_user_id FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.subscribers (user_id, email, subscribed, subscription_tier, ai_credits_limit, ai_credits_remaining)
    VALUES (p_user_id, (SELECT email FROM auth.users WHERE id = p_user_id), false, 'free', 10, 10)
    RETURNING * INTO v_subscriber;
  END IF;

  IF v_subscriber.ai_credits_reset_date <= NOW() THEN
    UPDATE public.subscribers
    SET ai_credits_remaining = ai_credits_limit,
        ai_credits_reset_date = NOW() + interval '1 month'
    WHERE user_id = p_user_id
    RETURNING * INTO v_subscriber;
  END IF;

  IF v_subscriber.ai_credits_remaining < p_credits_to_deduct THEN
    RETURN json_build_object(
      'success', false, 'error', 'insufficient_credits',
      'credits_remaining', v_subscriber.ai_credits_remaining,
      'credits_limit', v_subscriber.ai_credits_limit,
      'reset_date', v_subscriber.ai_credits_reset_date,
      'subscription_tier', v_subscriber.subscription_tier);
  END IF;

  UPDATE public.subscribers
  SET ai_credits_remaining = ai_credits_remaining - p_credits_to_deduct
  WHERE user_id = p_user_id
  RETURNING json_build_object(
    'success', true,
    'credits_remaining', ai_credits_remaining,
    'credits_limit', ai_credits_limit,
    'reset_date', ai_credits_reset_date,
    'subscription_tier', subscription_tier) INTO v_result;

  RETURN v_result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.check_trial_status(user_id_param uuid)
 RETURNS TABLE(is_trial_active boolean, trial_expired boolean, days_remaining integer, trial_ends_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  profile_record RECORD;
  days_left INTEGER;
BEGIN
  -- Get profile data
  SELECT * INTO profile_record 
  FROM public.profiles 
  WHERE id = user_id_param;
  
  IF NOT FOUND THEN
    RETURN;
  END IF;
  
  -- Calculate days remaining
  days_left := EXTRACT(DAY FROM (profile_record.trial_ends_at - NOW()));
  
  -- Update trial status if expired
  IF NOW() > profile_record.trial_ends_at AND profile_record.is_trial_active THEN
    UPDATE public.profiles 
    SET is_trial_active = false, trial_expired = true
    WHERE id = user_id_param;
    
    profile_record.is_trial_active := false;
    profile_record.trial_expired := true;
  END IF;
  
  RETURN QUERY SELECT 
    profile_record.is_trial_active,
    profile_record.trial_expired,
    GREATEST(0, days_left),
    profile_record.trial_ends_at;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cleanup_expired_2fa_codes()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  DELETE FROM public.user_2fa_codes 
  WHERE expires_at < now() OR used = true;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_payment_record(p_stripe_session_id text, p_customer_email text, p_amount integer, p_item_name text, p_user_id uuid DEFAULT NULL::uuid, p_customer_name text DEFAULT NULL::text, p_company_name text DEFAULT NULL::text, p_contact_number text DEFAULT NULL::text, p_currency text DEFAULT 'gbp'::text, p_payment_method text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    payment_id uuid;
BEGIN
    IF COALESCE(auth.role(), current_user) NOT IN ('service_role', 'postgres', 'supabase_admin') THEN
        RAISE EXCEPTION 'Not authorized';
    END IF;

    INSERT INTO public.payments (
        stripe_session_id, user_id, customer_email, customer_name, company_name,
        contact_number, amount, currency, item_name, payment_method, metadata, status)
    VALUES (
        p_stripe_session_id,
        p_user_id,
        public.encrypt_payment_data(p_customer_email),
        CASE WHEN p_customer_name IS NOT NULL THEN public.encrypt_payment_data(p_customer_name) END,
        CASE WHEN p_company_name IS NOT NULL THEN public.encrypt_payment_data(p_company_name) END,
        CASE WHEN p_contact_number IS NOT NULL THEN public.encrypt_payment_data(p_contact_number) END,
        p_amount, p_currency, p_item_name, p_payment_method, p_metadata, 'pending')
    RETURNING id INTO payment_id;

    INSERT INTO public.payment_audit_logs (user_id, payment_id, action, ip_address)
    VALUES (p_user_id, payment_id, 'payment_created', inet_client_addr());

    RETURN payment_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_team_with_owner(p_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid := auth.uid();
  v_org_id uuid;
  v_slug text;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF p_name IS NULL OR length(trim(p_name)) = 0 THEN
    RAISE EXCEPTION 'Team name is required';
  END IF;

  v_slug := lower(regexp_replace(p_name, '[^a-zA-Z0-9]+', '-', 'g'))
            || '-' || substr(md5(random()::text || clock_timestamp()::text), 1, 8);

  INSERT INTO public.organizations (name, slug, created_by, is_active)
  VALUES (trim(p_name), v_slug, v_uid, true)
  RETURNING id INTO v_org_id;

  INSERT INTO public.organization_members (organization_id, user_id, role, is_active)
  VALUES (v_org_id, v_uid, 'owner', true)
  ON CONFLICT (organization_id, user_id) DO UPDATE
    SET role = 'owner', is_active = true;

  RETURN v_org_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.create_user_organization()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  org_id UUID;
BEGIN
  -- Create personal organization for the user
  INSERT INTO public.organizations (name, slug, created_by)
  VALUES (
    COALESCE(NEW.raw_user_meta_data->>'full_name', SPLIT_PART(NEW.email, '@', 1)) || '''s Organization',
    LOWER(REPLACE(COALESCE(NEW.raw_user_meta_data->>'full_name', SPLIT_PART(NEW.email, '@', 1)), ' ', '-')) || '-org-' || EXTRACT(epoch FROM now())::text,
    NEW.id
  )
  RETURNING id INTO org_id;
  
  -- Add user as owner of the organization
  INSERT INTO public.organization_members (organization_id, user_id, role)
  VALUES (org_id, NEW.id, 'owner');
  
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.decrypt_banking_data(encrypted_data text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    decrypted_data text;
BEGIN
    IF encrypted_data IS NULL OR encrypted_data = '' THEN
        RETURN NULL;
    END IF;
    
    -- If encrypted with our format, decrypt it
    IF encrypted_data LIKE 'ENC:%' THEN
        BEGIN
            decrypted_data := convert_from(decode(substring(encrypted_data from 5), 'base64'), 'UTF8');
        EXCEPTION WHEN OTHERS THEN
            -- If decryption fails, return NULL for security
            RETURN NULL;
        END;
    ELSE
        -- Plain text data (backward compatibility)
        decrypted_data := encrypted_data;
    END IF;
    
    RETURN decrypted_data;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.decrypt_hmrc_token(encrypted_token text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  decrypted_token TEXT;
BEGIN
  IF encrypted_token IS NULL OR encrypted_token = '' THEN
    RETURN NULL;
  END IF;
  
  IF encrypted_token LIKE 'ENC:%' THEN
    BEGIN
      decrypted_token := convert_from(decode(substring(encrypted_token from 5), 'base64'), 'UTF8');
    EXCEPTION WHEN OTHERS THEN
      RETURN NULL;
    END;
  ELSE
    decrypted_token := encrypted_token;
  END IF;
  
  RETURN decrypted_token;
END;
$function$
;

