CREATE OR REPLACE FUNCTION public.encrypt_banking_data(data text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    encrypted_data text;
BEGIN
    IF data IS NULL OR data = '' THEN
        RETURN NULL;
    END IF;
    
    -- Use base64 encoding as basic encryption (better than plain text)
    encrypted_data := encode(convert_to(data, 'UTF8'), 'base64');
    RETURN 'ENC:' || encrypted_data;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.encrypt_hmrc_settings_secret()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF NEW.client_secret IS NOT NULL
     AND NEW.client_secret <> ''
     AND NEW.client_secret NOT LIKE 'ENC:%' THEN
    NEW.client_secret := public.encrypt_hmrc_token(NEW.client_secret);
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.encrypt_hmrc_token(token text)
