 RETURNS TABLE(email_task_assigned boolean, email_task_completed boolean, email_task_status_changed boolean, email_task_due_reminder boolean, email_task_overdue boolean, email_task_comment boolean, email_project_update boolean, email_weekly_digest boolean, due_reminder_hours integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  -- Insert default preferences if they don't exist
  INSERT INTO public.user_notification_preferences (user_id)
  VALUES (p_user_id)
  ON CONFLICT (user_id) DO NOTHING;
  
  -- Return the preferences
  RETURN QUERY
  SELECT 
    np.email_task_assigned,
    np.email_task_completed,
    np.email_task_status_changed,
    np.email_task_due_reminder,
    np.email_task_overdue,
    np.email_task_comment,
    np.email_project_update,
    np.email_weekly_digest,
    np.due_reminder_hours
  FROM public.user_notification_preferences np
  WHERE np.user_id = p_user_id;
