 RETURNS TABLE(id uuid, display_name text, avatar_url text, headline text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT 
    id,
    display_name,
    avatar_url,
    headline
  FROM public.public_profiles
  WHERE id = p_user_id
  LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_integrations_safe(p_user_id uuid DEFAULT auth.uid())
 RETURNS TABLE(id uuid, user_id uuid, integration_name text, is_connected boolean, connected_at timestamp with time zone, expires_at timestamp with time zone, metadata jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, has_access_token boolean, has_refresh_token boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  is_admin boolean;
BEGIN
  -- Check if user is admin/owner
  SELECT public.is_admin_or_owner(auth.uid()) INTO is_admin;
  
  -- Security check: users can only access their own integrations unless they're admin
  IF p_user_id != auth.uid() AND NOT COALESCE(is_admin, false) THEN
    RAISE EXCEPTION 'Access denied: Cannot access other users integration data';
  END IF;
  
  -- Audit log the access
  INSERT INTO public.integration_audit_logs (user_id, integration_name, action, ip_address)
  VALUES (p_user_id, 'all_integrations', 'safe_access', inet_client_addr());
  
  -- Return safe integration data (no tokens)
  RETURN QUERY
  SELECT 
    ui.id,
    ui.user_id,
    ui.integration_name,
    ui.is_connected,
    ui.connected_at,
    ui.expires_at,
    ui.metadata,
    ui.created_at,
    ui.updated_at,
    (ui.access_token IS NOT NULL) as has_access_token,
    (ui.refresh_token IS NOT NULL) as has_refresh_token
  FROM public.user_integrations ui
  WHERE ui.user_id = p_user_id
  ORDER BY ui.created_at DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_payments(p_user_id uuid DEFAULT auth.uid())
 RETURNS TABLE(id uuid, stripe_session_id text, amount integer, currency text, status text, item_name text, payment_method text, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
    -- Security check: users can only access their own payments
    IF p_user_id != auth.uid() AND NOT is_admin_or_owner(auth.uid()) THEN
        RAISE EXCEPTION 'Access denied: Cannot access other users payment data';
    END IF;
    
    -- Audit log the access
    INSERT INTO public.payment_audit_logs (user_id, action, ip_address)
    VALUES (p_user_id, 'payments_accessed', inet_client_addr());
    
    -- Return safe payment data (no sensitive customer info)
    RETURN QUERY
    SELECT 
        p.id,
        p.stripe_session_id,
        p.amount,
        p.currency,
        p.status,
        p.item_name,
        p.payment_method,
        p.created_at,
        p.updated_at
    FROM public.payments p
    WHERE p.user_id = p_user_id
    ORDER BY p.created_at DESC;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_projects(p_user_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  result JSON;
BEGIN
  IF auth.uid() IS NULL OR (p_user_id <> auth.uid() AND NOT public.is_super_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT json_agg(DISTINCT jsonb_build_object(
      'id', p.id, 'name', p.name, 'description', p.description,
      'status', p.status, 'progress', p.progress, 'deadline', p.deadline,
      'client', p.client, 'color', p.color, 'created_at', p.created_at,
      'updated_at', p.updated_at, 'budget', p.budget,
      'priority', p.priority, 'stage', p.stage))
  INTO result
  FROM public.projects p
  LEFT JOIN public.organization_members om
    ON p.organization_id = om.organization_id AND COALESCE(om.is_active, true)
  LEFT JOIN public.project_members pm ON p.id = pm.project_id
  WHERE om.user_id = p_user_id OR pm.user_id = p_user_id OR p.user_id = p_user_id;

  RETURN COALESCE(result, '[]'::json);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_staking_tier(_user_id uuid)
 RETURNS TABLE(tier_id uuid, tier_name text, total_staked numeric, monthly_credits integer, apy_percentage numeric, badge_color text, perks jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH user_total AS (
    SELECT COALESCE(SUM(amount), 0) AS total
    FROM public.user_stakes
    WHERE user_id = _user_id AND status = 'active'
  )
  SELECT 
    st.id,
    st.name,
    ut.total,
    st.monthly_credits,
    st.apy_percentage,
    st.badge_color,
    st.perks
  FROM public.staking_tiers st, user_total ut
  WHERE st.is_active = true AND st.min_stake_amount <= ut.total
  ORDER BY st.min_stake_amount DESC
  LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.get_user_teams(p_user_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  result JSON;
BEGIN
  IF auth.uid() IS NULL OR (p_user_id <> auth.uid() AND NOT public.is_super_admin(auth.uid())) THEN
    RAISE EXCEPTION 'Not authorized';
  END IF;

  SELECT json_agg(json_build_object('id', t.id, 'name', t.name, 'created_at', t.created_at))
  INTO result
  FROM public.teams t
  INNER JOIN public.team_members tm ON t.id = tm.team_id
  WHERE tm.user_id = p_user_id;

  RETURN COALESCE(result, '[]'::json);
END;
$function$
;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  new_org_id uuid;
  user_display_name text;
BEGIN
  -- Determine display name
  user_display_name := COALESCE(
    NEW.raw_user_meta_data->>'display_name',
    NEW.raw_user_meta_data->>'full_name', 
    split_part(NEW.email, '@', 1)
  );

  -- Create profile for new user
  INSERT INTO public.profiles (
    id,
    email,
    full_name,
    display_name,
    is_active,
    created_at,
    updated_at
  )
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', user_display_name),
    user_display_name,
    true,
    NOW(),
    NOW()
  )
  ON CONFLICT (id) DO UPDATE
  SET
    email = EXCLUDED.email,
    display_name = COALESCE(EXCLUDED.display_name, public.profiles.display_name, EXCLUDED.email),
    updated_at = NOW();

  -- Create organization if doesn't exist
  IF NOT EXISTS (
    SELECT 1 FROM public.organization_members WHERE user_id = NEW.id
  ) THEN
    INSERT INTO public.organizations (
      name,
      slug,
      created_by,
      is_active,
      created_at,
      updated_at
    )
    VALUES (
      user_display_name || '''s Organization',
      'org-' || SUBSTRING(NEW.id::text, 1, 8),
      NEW.id,
      true,
      NOW(),
      NOW()
    )
    RETURNING id INTO new_org_id;

    -- Add user as admin
    INSERT INTO public.organization_members (
      organization_id,
      user_id,
      role,
      is_active,
      joined_at,
      created_at,
      updated_at
    )
    VALUES (
      new_org_id,
      NEW.id,
      'admin',
      true,
      NOW(),
      NOW(),
      NOW()
    );
  END IF;

  RETURN NEW;
END;
$function$
;

