CREATE OR REPLACE FUNCTION public.preview_user_emissions(_user_id uuid)
 RETURNS TABLE(pool_id uuid, pool_name text, user_weighted_stake numeric, total_weighted_stake numeric, user_share_percent numeric, pool_remaining numeric, emission_per_second numeric, user_emission_per_day numeric, user_pending_since_last_claim numeric, next_claim_available_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_pool RECORD;
  v_user_weight NUMERIC := 0;
  v_total_weight NUMERIC := 0;
  v_last_claim TIMESTAMPTZ;
  v_seconds_since NUMERIC;
  v_share NUMERIC := 0;
BEGIN
  SELECT * INTO v_pool
  FROM public.staking_reward_pools
  WHERE is_active = true AND now() BETWEEN start_date AND end_date
  ORDER BY start_date DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT COALESCE(SUM(amount * apy_percentage), 0) INTO v_user_weight
  FROM public.user_stakes
  WHERE user_id = _user_id AND status = 'active';

  SELECT COALESCE(SUM(amount * apy_percentage), 0) INTO v_total_weight
  FROM public.user_stakes
  WHERE status = 'active';

  IF v_total_weight > 0 THEN
    v_share := v_user_weight / v_total_weight;
  END IF;

  SELECT COALESCE(MAX(last_claim_at), MIN(staked_at)) INTO v_last_claim
  FROM public.user_stakes
  WHERE user_id = _user_id AND status = 'active';

  v_seconds_since := EXTRACT(EPOCH FROM (now() - COALESCE(v_last_claim, now())));

  RETURN QUERY SELECT
    v_pool.id,
    v_pool.name,
    v_user_weight,
    v_total_weight,
    ROUND(v_share * 100, 4),
    GREATEST(v_pool.total_budget - v_pool.emitted_amount, 0),
    v_pool.emission_per_second,
    ROUND(v_pool.emission_per_second * v_share * 86400, 6),
    ROUND(v_pool.emission_per_second * v_share * v_seconds_since, 6),
    COALESCE(v_last_claim, now()) + interval '7 days';
END;
$function$
;

CREATE OR REPLACE FUNCTION public.rota_can_add_employee(p_org_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_count integer;
  v_tier text;
  v_owner uuid;
BEGIN
  -- Must be admin in org
  IF NOT public.user_is_organization_admin(p_org_id, auth.uid()) THEN
    RETURN false;
  END IF;

  -- Find org owner
  SELECT user_id INTO v_owner
  FROM public.organization_members
  WHERE organization_id = p_org_id AND role = 'owner' AND is_active = true
  LIMIT 1;

  -- Check tier on owner's subscriber record
  SELECT lower(coalesce(subscription_tier,'free')) INTO v_tier
  FROM public.subscribers
  WHERE user_id = v_owner
  LIMIT 1;

  IF v_tier IN ('business premium','business_premium','premium','enterprise','business-premium') THEN
    RETURN true;
  END IF;

  SELECT count(*) INTO v_count
  FROM public.rota_employees
  WHERE organization_id = p_org_id AND is_active = true;

  RETURN v_count < 3;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.store_bank_account(p_account_id text, p_provider_id text, p_provider_name text, p_account_type text, p_account_number text DEFAULT NULL::text, p_sort_code text DEFAULT NULL::text, p_currency text DEFAULT 'GBP'::text, p_balance numeric DEFAULT NULL::numeric, p_available_balance numeric DEFAULT NULL::numeric, p_user_id uuid DEFAULT auth.uid())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    bank_account_id uuid;
    encrypted_account_number text;
    encrypted_sort_code text;
BEGIN
    -- Verify user can only store their own banking data
    IF p_user_id != auth.uid() AND NOT is_admin_or_owner(auth.uid()) THEN
        RAISE EXCEPTION 'Access denied: Cannot store banking data for other users';
    END IF;
    
    -- Encrypt sensitive data
    encrypted_account_number := CASE 
        WHEN p_account_number IS NOT NULL THEN public.encrypt_banking_data(p_account_number)
        ELSE NULL
    END;
    encrypted_sort_code := CASE 
        WHEN p_sort_code IS NOT NULL THEN public.encrypt_banking_data(p_sort_code)
        ELSE NULL
    END;
    
    -- Insert or update the bank account
    INSERT INTO public.bank_accounts (
        user_id,
        account_id,
        provider_id,
        provider_name,
        account_type,
        account_number,
        sort_code,
        currency,
        balance,
        available_balance,
        is_active
    )
    VALUES (
        p_user_id,
        p_account_id,
        p_provider_id,
        p_provider_name,
        p_account_type,
        encrypted_account_number,
        encrypted_sort_code,
        p_currency,
        p_balance,
        p_available_balance,
        true
    )
    ON CONFLICT (user_id, account_id) 
    DO UPDATE SET
        provider_name = EXCLUDED.provider_name,
        account_type = EXCLUDED.account_type,
        account_number = EXCLUDED.account_number,
        sort_code = EXCLUDED.sort_code,
        currency = EXCLUDED.currency,
        balance = EXCLUDED.balance,
        available_balance = EXCLUDED.available_balance,
        updated_at = now()
    RETURNING id INTO bank_account_id;
    
    -- Log the banking data storage
    INSERT INTO public.banking_audit_logs (user_id, bank_account_id, action, ip_address)
    VALUES (p_user_id, bank_account_id, 'account_stored', inet_client_addr());
    
    RETURN bank_account_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.store_integration_tokens(p_integration_name text, p_access_token text, p_refresh_token text DEFAULT NULL::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_metadata jsonb DEFAULT '{}'::jsonb, p_user_id uuid DEFAULT auth.uid())
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
    integration_id uuid;
    encrypted_access_token text;
    encrypted_refresh_token text;
BEGIN
    -- Verify user can only store their own tokens
    IF p_user_id != auth.uid() AND NOT is_admin_or_owner(auth.uid()) THEN
        RAISE EXCEPTION 'Access denied: Cannot store tokens for other users';
    END IF;
    
    -- Encrypt the tokens
    encrypted_access_token := public.encrypt_integration_token(p_access_token);
    encrypted_refresh_token := CASE 
        WHEN p_refresh_token IS NOT NULL THEN public.encrypt_integration_token(p_refresh_token)
        ELSE NULL
    END;
    
    -- Insert or update the integration
    INSERT INTO public.user_integrations (
        user_id,
        integration_name,
        access_token,
        refresh_token,
        expires_at,
        metadata,
        is_connected,
        connected_at
    )
    VALUES (
        p_user_id,
        p_integration_name,
        encrypted_access_token,
        encrypted_refresh_token,
        p_expires_at,
        p_metadata,
        true,
        now()
    )
    ON CONFLICT (user_id, integration_name) 
    DO UPDATE SET
        access_token = EXCLUDED.access_token,
        refresh_token = EXCLUDED.refresh_token,
        expires_at = EXCLUDED.expires_at,
        metadata = EXCLUDED.metadata,
        is_connected = EXCLUDED.is_connected,
        connected_at = EXCLUDED.connected_at,
        updated_at = now()
    RETURNING id INTO integration_id;
    
    -- Log the token storage
    INSERT INTO public.integration_audit_logs (user_id, integration_name, action, ip_address)
    VALUES (p_user_id, p_integration_name, 'token_created', inet_client_addr());
    
    RETURN integration_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.template_usage_counts()
