CREATE OR REPLACE FUNCTION public.user_is_organization_owner(org_id uuid, check_user_id uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.organization_members om
    WHERE om.organization_id = org_id
      AND om.user_id = check_user_id
      AND om.role = 'owner'
      AND om.is_active = true
  );
$function$
;

CREATE OR REPLACE FUNCTION public.user_owns_project(project_id uuid, check_user_id uuid DEFAULT auth.uid())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT EXISTS (
    SELECT 1 
    FROM public.projects p
    WHERE p.id = project_id 
      AND p.user_id = check_user_id
  );
$function$
;

CREATE OR REPLACE FUNCTION public.users_share_organization(_a uuid, _b uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.organization_members m1
    JOIN public.organization_members m2
      ON m1.organization_id = m2.organization_id
    WHERE m1.user_id = _a AND m2.user_id = _b
      AND COALESCE(m1.is_active, true) AND COALESCE(m2.is_active, true)
  );
$function$
;



