-- POLICIES
CREATE POLICY "super admins append audit" ON public.admin_audit_logs AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((is_super_admin(auth.uid()) AND (admin_id = auth.uid())));
CREATE POLICY "super admins read audit" ON public.admin_audit_logs AS PERMISSIVE FOR SELECT TO authenticated
  USING (is_super_admin(auth.uid()));
CREATE POLICY "Anyone can view advertisement categories" ON public.advertisement_categories AS PERMISSIVE FOR SELECT TO public
  USING (true);
CREATE POLICY "System can manage advertisement categories" ON public.advertisement_categories AS PERMISSIVE FOR ALL TO public
  USING (false)
  WITH CHECK (false);
CREATE POLICY "Anyone signed in can browse active advertisements" ON public.advertisements AS PERMISSIVE FOR SELECT TO authenticated
  USING ((is_active = true));
CREATE POLICY "Users can create their own advertisements" ON public.advertisements AS PERMISSIVE FOR INSERT TO public
  WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "Users can delete their own advertisements" ON public.advertisements AS PERMISSIVE FOR DELETE TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can update their own advertisements" ON public.advertisements AS PERMISSIVE FOR UPDATE TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can view their own advertisements" ON public.advertisements AS PERMISSIVE FOR SELECT TO public
  USING ((auth.uid() = user_id));
