  USING ((auth.uid() = user_id));
CREATE POLICY "Users can view their own workspaces" ON public.ai_workspaces AS PERMISSIVE FOR SELECT TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Service role can insert audit logs" ON public.audit_logs AS PERMISSIVE FOR INSERT TO service_role
  WITH CHECK (true);
CREATE POLICY "Super admins can view all audit logs" ON public.audit_logs AS PERMISSIVE FOR SELECT TO authenticated
  USING (is_super_admin(auth.uid()));
CREATE POLICY "Users can view their own audit logs" ON public.audit_logs AS PERMISSIVE FOR SELECT TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Admins can view all B2B submissions" ON public.b2b_form_submissions AS PERMISSIVE FOR SELECT TO public
  USING (is_admin_or_owner(auth.uid()));
