  WITH CHECK ((auth.uid() = created_by));
CREATE POLICY "Company creators can update their companies" ON public.companies AS PERMISSIVE FOR UPDATE TO public
  USING ((auth.uid() = created_by));
CREATE POLICY "Company creators can view their companies" ON public.companies AS PERMISSIVE FOR SELECT TO authenticated
  USING (((auth.uid() = created_by) OR is_super_admin(auth.uid())));
CREATE POLICY "Authenticated users can create connections" ON public.connections AS PERMISSIVE FOR INSERT TO public
  WITH CHECK ((auth.uid() = requester_id));
CREATE POLICY "Users can update their connection requests" ON public.connections AS PERMISSIVE FOR UPDATE TO public
  USING (((auth.uid() = requester_id) OR (auth.uid() = addressee_id)));
CREATE POLICY "Users can view their connections" ON public.connections AS PERMISSIVE FOR SELECT TO public
  USING (((auth.uid() = requester_id) OR (auth.uid() = addressee_id)));
CREATE POLICY "Users can manage their own contacts" ON public.crm_contacts AS PERMISSIVE FOR ALL TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can manage their own deals" ON public.crm_deals AS PERMISSIVE FOR ALL TO public
  USING ((auth.uid() = user_id));
CREATE POLICY documents_delete_own_or_super_admin ON public.documents AS PERMISSIVE FOR DELETE TO authenticated
  USING (((auth.uid() = user_id) OR is_super_admin(auth.uid())));
CREATE POLICY documents_insert_own_or_super_admin ON public.documents AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((auth.uid() = user_id) OR is_super_admin(auth.uid())));
CREATE POLICY documents_select_owned_purchased_or_free ON public.documents AS PERMISSIVE FOR SELECT TO authenticated
  USING (((auth.uid() = user_id) OR is_super_admin(auth.uid()) OR (COALESCE(price, (0)::numeric) = (0)::numeric) OR (EXISTS ( SELECT 1
   FROM user_documents ud
  WHERE ((ud.document_id = documents.id) AND (ud.user_id = auth.uid()))))));
CREATE POLICY documents_update_own_or_super_admin ON public.documents AS PERMISSIVE FOR UPDATE TO authenticated
  USING (((auth.uid() = user_id) OR is_super_admin(auth.uid())))
  WITH CHECK (((auth.uid() = user_id) OR is_super_admin(auth.uid())));
CREATE POLICY "Users can manage their own expenses" ON public.expenses AS PERMISSIVE FOR ALL TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Admins can update feedback/requests" ON public.feedback_requests AS PERMISSIVE FOR UPDATE TO public
  USING ((has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'owner'::app_role)));
CREATE POLICY "Admins can view all feedback/requests" ON public.feedback_requests AS PERMISSIVE FOR SELECT TO public
  USING ((has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'owner'::app_role)));
