CREATE POLICY team_members_view_own ON public.team_members AS PERMISSIVE FOR SELECT TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Team owners can update their teams" ON public.teams AS PERMISSIVE FOR UPDATE TO public
  USING ((owner_id = auth.uid()));
CREATE POLICY "Users can create their own teams" ON public.teams AS PERMISSIVE FOR INSERT TO public
  WITH CHECK ((owner_id = auth.uid()));
CREATE POLICY "Users can view teams they own or belong to" ON public.teams AS PERMISSIVE FOR SELECT TO public
  USING (((owner_id = auth.uid()) OR (id IN ( SELECT team_members.team_id
   FROM team_members
  WHERE (team_members.user_id = auth.uid())))));
CREATE POLICY "Published templates are readable by everyone" ON public.template_catalog AS PERMISSIVE FOR SELECT TO public
  USING ((status = 'published'::text));
CREATE POLICY "Super admins can delete templates" ON public.template_catalog AS PERMISSIVE FOR DELETE TO authenticated
  USING (is_super_admin(auth.uid()));
CREATE POLICY "Super admins can insert templates" ON public.template_catalog AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (is_super_admin(auth.uid()));
CREATE POLICY "Super admins can read all templates" ON public.template_catalog AS PERMISSIVE FOR SELECT TO authenticated
  USING (is_super_admin(auth.uid()));
CREATE POLICY "Super admins can update templates" ON public.template_catalog AS PERMISSIVE FOR UPDATE TO authenticated
  USING (is_super_admin(auth.uid()))
  WITH CHECK (is_super_admin(auth.uid()));
CREATE POLICY "Anyone can record their own template activity" ON public.template_events AS PERMISSIVE FOR INSERT TO public
  WITH CHECK ((NOT (user_id IS DISTINCT FROM auth.uid())));
CREATE POLICY "Super admins can read template activity" ON public.template_events AS PERMISSIVE FOR SELECT TO authenticated
  USING (is_super_admin(auth.uid()));
CREATE POLICY "Users can create comments on their todos" ON public.todo_comments AS PERMISSIVE FOR INSERT TO public
  WITH CHECK (((auth.uid() = user_id) AND (EXISTS ( SELECT 1
   FROM todos
  WHERE ((todos.id = todo_comments.todo_id) AND ((todos.user_id = auth.uid()) OR (todos.assigned_to = auth.uid())))))));
CREATE POLICY "Users can delete their own comments" ON public.todo_comments AS PERMISSIVE FOR DELETE TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can view comments on their todos" ON public.todo_comments AS PERMISSIVE FOR SELECT TO public
  USING ((EXISTS ( SELECT 1
   FROM todos
  WHERE ((todos.id = todo_comments.todo_id) AND ((todos.user_id = auth.uid()) OR (todos.assigned_to = auth.uid()))))));
CREATE POLICY "Users can insert history for their todos" ON public.todo_history AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((user_id = auth.uid()) AND (EXISTS ( SELECT 1
   FROM todos t
  WHERE ((t.id = todo_history.todo_id) AND ((t.user_id = auth.uid()) OR (t.assigned_to = auth.uid())))))));
CREATE POLICY "Users can view history of their todos" ON public.todo_history AS PERMISSIVE FOR SELECT TO public
  USING ((EXISTS ( SELECT 1
   FROM todos
  WHERE ((todos.id = todo_history.todo_id) AND ((todos.user_id = auth.uid()) OR (todos.assigned_to = auth.uid()))))));
CREATE POLICY "Users can create subtasks for their todos" ON public.todo_subtasks AS PERMISSIVE FOR INSERT TO public
  WITH CHECK ((EXISTS ( SELECT 1
   FROM todos
  WHERE ((todos.id = todo_subtasks.todo_id) AND (todos.user_id = auth.uid())))));
CREATE POLICY "Users can delete subtasks of their todos" ON public.todo_subtasks AS PERMISSIVE FOR DELETE TO public
  USING ((EXISTS ( SELECT 1
   FROM todos
  WHERE ((todos.id = todo_subtasks.todo_id) AND (todos.user_id = auth.uid())))));
CREATE POLICY "Users can update subtasks of their todos" ON public.todo_subtasks AS PERMISSIVE FOR UPDATE TO public
  USING ((EXISTS ( SELECT 1
   FROM todos
  WHERE ((todos.id = todo_subtasks.todo_id) AND (todos.user_id = auth.uid())))));
CREATE POLICY "Users can view subtasks of their todos" ON public.todo_subtasks AS PERMISSIVE FOR SELECT TO public
  USING ((EXISTS ( SELECT 1
   FROM todos
  WHERE ((todos.id = todo_subtasks.todo_id) AND (todos.user_id = auth.uid())))));
CREATE POLICY "Organization members can manage todos" ON public.todos AS PERMISSIVE FOR ALL TO public
  USING (user_is_organization_member(organization_id))
  WITH CHECK (user_is_organization_member(organization_id));
CREATE POLICY "Organization members can view todos" ON public.todos AS PERMISSIVE FOR SELECT TO public
  USING (user_is_organization_member(organization_id));
CREATE POLICY "Users can manage personal todos" ON public.todos AS PERMISSIVE FOR ALL TO authenticated
  USING (((organization_id IS NULL) AND (auth.uid() = user_id)))
  WITH CHECK (((organization_id IS NULL) AND (auth.uid() = user_id)));
CREATE POLICY "Users can manage todos in their organization" ON public.todos AS PERMISSIVE FOR ALL TO public
  USING ((organization_id IN ( SELECT om.organization_id
   FROM organization_members om
  WHERE ((om.user_id = auth.uid()) AND (om.is_active = true)))));
CREATE POLICY "Service role can manage 2FA attempts" ON public.user_2fa_attempts AS PERMISSIVE FOR ALL TO service_role
  USING (true)
  WITH CHECK (true);
CREATE POLICY "Users can view their own 2FA attempts" ON public.user_2fa_attempts AS PERMISSIVE FOR SELECT TO public
  USING (((auth.uid() = user_id) OR (email = auth.email())));
CREATE POLICY "Block anonymous access to 2FA codes" ON public.user_2fa_codes AS PERMISSIVE FOR ALL TO anon
  USING (false)
  WITH CHECK (false);
CREATE POLICY "Block authenticated direct access to 2FA codes" ON public.user_2fa_codes AS RESTRICTIVE FOR ALL TO authenticated
  USING (false)
  WITH CHECK (false);
CREATE POLICY "System can manage 2FA codes" ON public.user_2fa_codes AS PERMISSIVE FOR ALL TO service_role
  USING (true)
  WITH CHECK (true);
CREATE POLICY "Users can manage their own 2FA settings" ON public.user_2fa_settings AS PERMISSIVE FOR ALL TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can create their own preferences" ON public.user_ai_preferences AS PERMISSIVE FOR INSERT TO public
  WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "Users can update their own preferences" ON public.user_ai_preferences AS PERMISSIVE FOR UPDATE TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can view their own preferences" ON public.user_ai_preferences AS PERMISSIVE FOR SELECT TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users manage their own document template preferences" ON public.user_document_templates AS PERMISSIVE FOR ALL TO authenticated
  USING ((auth.uid() = user_id))
  WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "Users can insert their own purchases" ON public.user_documents AS PERMISSIVE FOR INSERT TO public
  WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "Users can update their own purchases" ON public.user_documents AS PERMISSIVE FOR UPDATE TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can view their own purchases" ON public.user_documents AS PERMISSIVE FOR SELECT TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can create their own favorites" ON public.user_favorite_tools AS PERMISSIVE FOR INSERT TO public
  WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "Users can delete their own favorites" ON public.user_favorite_tools AS PERMISSIVE FOR DELETE TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can view their own favorites" ON public.user_favorite_tools AS PERMISSIVE FOR SELECT TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can manage their own favorites" ON public.user_favorites AS PERMISSIVE FOR ALL TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can view their own favorites" ON public.user_favorites AS PERMISSIVE FOR SELECT TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "System functions can manage integrations" ON public.user_integrations AS PERMISSIVE FOR ALL TO public
  USING (false)
  WITH CHECK (false);
CREATE POLICY "Users can delete their own integrations" ON public.user_integrations AS PERMISSIVE FOR DELETE TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can view their own integration metadata (no tokens)" ON public.user_integrations AS PERMISSIVE FOR SELECT TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can insert own notification preferences" ON public.user_notification_preferences AS PERMISSIVE FOR INSERT TO public
  WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "Users can update own notification preferences" ON public.user_notification_preferences AS PERMISSIVE FOR UPDATE TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can view own notification preferences" ON public.user_notification_preferences AS PERMISSIVE FOR SELECT TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Super admins can delete customer roles" ON public.user_roles AS PERMISSIVE FOR DELETE TO authenticated
  USING ((is_super_admin(auth.uid()) AND (role <> 'super_admin'::app_role) AND (user_id <> auth.uid())));
CREATE POLICY "Super admins can insert customer roles" ON public.user_roles AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((is_super_admin(auth.uid()) AND (role <> 'super_admin'::app_role) AND (user_id <> auth.uid())));
CREATE POLICY "Super admins can update customer roles" ON public.user_roles AS PERMISSIVE FOR UPDATE TO authenticated
  USING ((is_super_admin(auth.uid()) AND (role <> 'super_admin'::app_role) AND (user_id <> auth.uid())))
  WITH CHECK ((is_super_admin(auth.uid()) AND (role <> 'super_admin'::app_role) AND (user_id <> auth.uid())));
CREATE POLICY "Super admins can view all roles" ON public.user_roles AS PERMISSIVE FOR SELECT TO authenticated
  USING (is_super_admin(auth.uid()));
CREATE POLICY "Users can view their own roles" ON public.user_roles AS PERMISSIVE FOR SELECT TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Admins can view all stakes" ON public.user_stakes AS PERMISSIVE FOR SELECT TO public
  USING (is_admin_or_owner(auth.uid()));
CREATE POLICY "Users can create their own stakes" ON public.user_stakes AS PERMISSIVE FOR INSERT TO public
  WITH CHECK ((auth.uid() = user_id));
CREATE POLICY "Users can update their own stakes" ON public.user_stakes AS PERMISSIVE FOR UPDATE TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users can view their own stakes" ON public.user_stakes AS PERMISSIVE FOR SELECT TO public
  USING ((auth.uid() = user_id));
CREATE POLICY "Users insert own run logs" ON public.workflow_run_logs AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK ((user_id = auth.uid()));
CREATE POLICY "Users view own run logs" ON public.workflow_run_logs AS PERMISSIVE FOR SELECT TO authenticated
  USING ((user_id = auth.uid()));
CREATE POLICY "Authenticated users can upload advertisement images" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'advertisement-images'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Authenticated users can upload service images" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'service-images'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Users can delete service images they uploaded" ON storage.objects AS PERMISSIVE FOR DELETE TO public
  USING (((bucket_id = 'service-images'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Users can delete their own advertisement images" ON storage.objects AS PERMISSIVE FOR DELETE TO public
  USING (((bucket_id = 'advertisement-images'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Users can delete their own avatars" ON storage.objects AS PERMISSIVE FOR DELETE TO public
  USING (((bucket_id = 'user-avatars'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Users can delete their own company logos" ON storage.objects AS PERMISSIVE FOR DELETE TO public
  USING (((bucket_id = 'company-logos'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Users can update service images they uploaded" ON storage.objects AS PERMISSIVE FOR UPDATE TO public
  USING (((bucket_id = 'service-images'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Users can update their own advertisement images" ON storage.objects AS PERMISSIVE FOR UPDATE TO public
  USING (((bucket_id = 'advertisement-images'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Users can update their own avatars" ON storage.objects AS PERMISSIVE FOR UPDATE TO public
  USING (((bucket_id = 'user-avatars'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Users can update their own company logos" ON storage.objects AS PERMISSIVE FOR UPDATE TO public
  USING (((bucket_id = 'company-logos'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Users can upload their own avatars" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'user-avatars'::text) AND ((auth.uid())::text = (storage.foldername(name))[1])));
CREATE POLICY "Users can upload their own company logos" ON storage.objects AS PERMISSIVE FOR INSERT TO authenticated
